-- Migration 00047: Convert roast_date from DATE to TIMESTAMPTZ
--
-- The migrate_sheets.py script stripped time components from roast_date
-- by calling .date() on parsed datetimes. This migration:
--   1. Changes the column type to timestamp with time zone
--   2. Backfills actual timestamps from the Google Sheets source
--   3. Recalculates coffee inventory (roast date boundaries may shift)

-- ═══════════════════════════════════════════════════════════════
-- A. DROP all dependent views, ALTER column type
-- ═══════════════════════════════════════════════════════════════
-- Three views reference roast_log.roast_date and block ALTER TYPE.
-- Indexes are automatically rebuilt by PostgreSQL.

DROP VIEW IF EXISTS public.weekly_grand_total;
DROP VIEW IF EXISTS public.roast_detail;
DROP VIEW IF EXISTS public.roast_detail_by_blend;

ALTER TABLE public.roast_log
  ALTER COLUMN roast_date TYPE timestamp with time zone
  USING roast_date::timestamp with time zone;

-- ── Recreate roast_detail_by_blend (from migration 00026) ───────────────

CREATE OR REPLACE VIEW public.roast_detail_by_blend
WITH (security_invoker='true') AS
WITH facility_params AS (
    SELECT
        f.facility_id,
        f.company_id,
        COALESCE(NULLIF(f.time_zone, ''), 'Pacific/Honolulu') AS timezone,
        COALESCE(
            (SELECT cp.value_number::integer
             FROM public.company_parameters cp
             WHERE cp.parameter_id = 'RF1iFWjOh7'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            4
        ) AS roast_reset_day,
        COALESCE(
            (SELECT cp.value_number
             FROM public.company_parameters cp
             WHERE cp.parameter_id = '761fd894'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            25
        ) AS charge_weight,
        COALESCE(
            (SELECT cp.value_number
             FROM public.company_parameters cp
             WHERE cp.parameter_id = '1de271df'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            0.82
        ) AS retention_rate
    FROM public.facilities f
),
calc AS (
    SELECT
        fp.facility_id,
        fp.company_id,
        fp.timezone,
        fp.charge_weight,
        fp.retention_rate,
        ((CURRENT_TIMESTAMP AT TIME ZONE fp.timezone)::date
            - ((EXTRACT(dow FROM (CURRENT_TIMESTAMP AT TIME ZONE fp.timezone)::date)::integer
                - fp.roast_reset_day + 7) % 7))  AS roast_week_start
    FROM facility_params fp
),
recipe_facility AS (
    SELECT rr.recipe_id, f.facility_id, f.company_id
    FROM public.roast_recipes rr
    JOIN public.facilities f
      ON f.company_id = rr.company_id
     AND (rr.facility_id IS NULL OR rr.facility_id = f.facility_id)
),
per_recipe AS (
    SELECT
        rf.recipe_id,
        rf.facility_id,
        rf.company_id,
        COALESCE(stock.in_stock_roasted, 0) AS in_stock_roasted,
        COALESCE(ordered.total_ordered, 0)  AS total_ordered,
        COALESCE(roasted.total_roasted, 0)  AS total_roasted,
        c.retention_rate,
        COALESCE(
            (SELECT AVG(charge_weight)
             FROM (
                 SELECT charge_weight
                 FROM public.roast_log
                 WHERE recipe_id    = rf.recipe_id
                   AND facility_id  = rf.facility_id
                   AND charge_weight > 0
                 ORDER BY roast_date DESC
                 LIMIT 5
             ) recent),
            c.charge_weight,
            25
        ) AS effective_charge_weight
    FROM recipe_facility rf
    JOIN calc c ON c.facility_id = rf.facility_id
    LEFT JOIN LATERAL (
        SELECT COALESCE(SUM(rsl.lbs_in_stock), 0) AS in_stock_roasted
        FROM public.roast_stock_log rsl
        WHERE rsl.blend_id    = rf.recipe_id
          AND rsl.facility_id = rf.facility_id
          AND (rsl.created_at AT TIME ZONE c.timezone)::date >= c.roast_week_start
    ) stock ON true
    LEFT JOIN LATERAL (
        SELECT SUM(od.roasted_weight) AS total_ordered
        FROM public.order_details od
        JOIN public.orders o   ON od.order_id  = o.order_id
        JOIN public.products p ON od.product_id = p.product_id
        WHERE p.recipe_id    = rf.recipe_id
          AND o.order_status = 'Open'
          AND o.facility_id  = rf.facility_id
    ) ordered ON true
    LEFT JOIN LATERAL (
        SELECT SUM(rl.roasted_weight) AS total_roasted
        FROM public.roast_log rl
        WHERE rl.recipe_id   = rf.recipe_id
          AND rl."charged?"  = true
          AND rl.roast_date >= c.roast_week_start
          AND rl.facility_id = rf.facility_id
    ) roasted ON true
)
SELECT
    recipe_id || '-' || facility_id                                AS roast_blend_id,
    recipe_id,
    facility_id,
    company_id,
    in_stock_roasted,
    total_ordered,
    total_roasted,
    GREATEST(0, total_ordered - in_stock_roasted - total_roasted) AS roasted_left,
    GREATEST(0, total_ordered - in_stock_roasted - total_roasted)
        / NULLIF(retention_rate, 0)
        / NULLIF(effective_charge_weight, 0)                       AS roasts_remaining
FROM per_recipe;

GRANT ALL ON TABLE public.roast_detail_by_blend TO anon;
GRANT ALL ON TABLE public.roast_detail_by_blend TO authenticated;
GRANT ALL ON TABLE public.roast_detail_by_blend TO service_role;

-- ── Recreate roast_detail (from migration 00026) ────────────────────────

CREATE OR REPLACE VIEW public.roast_detail
WITH (security_invoker='true') AS
WITH facility_params AS (
    SELECT
        f.facility_id,
        f.company_id,
        COALESCE(NULLIF(f.time_zone, ''), 'Pacific/Honolulu') AS timezone,
        COALESCE(
            (SELECT cp.value_number::integer
             FROM public.company_parameters cp
             WHERE cp.parameter_id = 'RF1iFWjOh7'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            4
        ) AS roast_reset_day,
        COALESCE(
            (SELECT cp.value_number
             FROM public.company_parameters cp
             WHERE cp.parameter_id = '761fd894'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            25
        ) AS charge_weight,
        COALESCE(
            (SELECT cp.value_number
             FROM public.company_parameters cp
             WHERE cp.parameter_id = '1de271df'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            0.82
        ) AS retention_rate
    FROM public.facilities f
),
calc AS (
    SELECT
        fp.facility_id,
        fp.company_id,
        fp.timezone,
        fp.charge_weight,
        fp.retention_rate,
        ((CURRENT_TIMESTAMP AT TIME ZONE fp.timezone)::date
            - ((EXTRACT(dow FROM (CURRENT_TIMESTAMP AT TIME ZONE fp.timezone)::date)::integer
                - fp.roast_reset_day + 7) % 7))  AS roast_week_start
    FROM facility_params fp
),
origin_facility AS (
    SELECT DISTINCT
        rc.coffee_item AS origin,
        f.facility_id,
        f.company_id
    FROM public.recipe_components rc
    JOIN public.roast_recipes rr ON rc.recipe_id = rr.recipe_id
    JOIN public.facilities f
      ON f.company_id = rr.company_id
     AND (rr.facility_id IS NULL OR rr.facility_id = f.facility_id)
),
per_origin AS (
    SELECT
        of2.origin,
        of2.facility_id,
        of2.company_id,
        COALESCE((
            SELECT SUM(rsl.lbs_in_stock)
            FROM public.roast_stock_log rsl
            WHERE rsl.origin_id   = of2.origin
              AND rsl.facility_id = of2.facility_id
              AND (rsl.created_at AT TIME ZONE c.timezone)::date >= c.roast_week_start
        ), 0)
        + COALESCE((
            SELECT SUM(rsl.lbs_in_stock * rc.percentage)
            FROM public.roast_stock_log rsl
            JOIN public.recipe_components rc ON rsl.blend_id = rc.recipe_id
            WHERE rc.coffee_item  = of2.origin
              AND rsl.facility_id = of2.facility_id
              AND (rsl.created_at AT TIME ZONE c.timezone)::date >= c.roast_week_start
        ), 0)                                                       AS in_stock_roasted,
        COALESCE((
            SELECT SUM(od.quantity * p.weight_lbs * rc.percentage)
            FROM public.order_details od
            JOIN public.orders o   ON od.order_id  = o.order_id
            JOIN public.products p ON od.product_id = p.product_id
            JOIN public.recipe_components rc ON p.recipe_id = rc.recipe_id
            WHERE rc.coffee_item  = of2.origin
              AND o.order_status  = 'Open'
              AND o.facility_id   = of2.facility_id
        ), 0)                                                       AS total_ordered,
        COALESCE((
            SELECT SUM(rl.roasted_weight)
            FROM public.roast_log rl
            WHERE rl.origin_id   = of2.origin
              AND rl."charged?"  = true
              AND rl.roast_date >= c.roast_week_start
              AND rl.facility_id = of2.facility_id
        ), 0)
        + COALESCE((
            SELECT SUM(rl.roasted_weight * rc.percentage)
            FROM public.roast_log rl
            JOIN public.roast_recipes rr ON rl.recipe_id = rr.recipe_id
            JOIN public.recipe_components rc ON rl.recipe_id = rc.recipe_id
            WHERE rr.roast_type  = 'Pre-Blend'
              AND rc.coffee_item = of2.origin
              AND rl."charged?"  = true
              AND rl.roast_date >= c.roast_week_start
              AND rl.facility_id = of2.facility_id
        ), 0)                                                       AS total_roasted,
        c.retention_rate,
        COALESCE(
            (SELECT AVG(charge_weight)
             FROM (
                 SELECT charge_weight
                 FROM public.roast_log
                 WHERE origin_id   = of2.origin
                   AND facility_id = of2.facility_id
                   AND charge_weight > 0
                 ORDER BY roast_date DESC
                 LIMIT 5
             ) recent),
            c.charge_weight,
            25
        ) AS effective_charge_weight
    FROM origin_facility of2
    JOIN calc c ON c.facility_id = of2.facility_id
)
SELECT
    origin || '-' || facility_id                                   AS roast_detail_id,
    origin,
    facility_id,
    company_id,
    in_stock_roasted,
    total_roasted,
    total_ordered,
    GREATEST(0, total_ordered - in_stock_roasted - total_roasted) AS final_roasted_weight,
    GREATEST(0, total_ordered - in_stock_roasted - total_roasted)
        / NULLIF(retention_rate, 0)                                AS green_to_roast,
    GREATEST(0, total_ordered - in_stock_roasted - total_roasted)
        / NULLIF(retention_rate, 0)
        / NULLIF(effective_charge_weight, 0)                       AS roasts_remaining
FROM per_origin;

GRANT ALL ON TABLE public.roast_detail TO anon;
GRANT ALL ON TABLE public.roast_detail TO authenticated;
GRANT ALL ON TABLE public.roast_detail TO service_role;

-- ── Recreate weekly_grand_total (from migration 00015) ──────────────────

CREATE OR REPLACE VIEW public.weekly_grand_total
WITH (security_invoker='true') AS
WITH facility_config AS (
    SELECT
        f.facility_id,
        f.company_id,
        COALESCE(NULLIF(f.time_zone, ''), 'UTC') AS timezone,
        COALESCE(
            (SELECT cp.value_number::integer
             FROM public.company_parameters cp
             WHERE cp.parameter_id = 'RF1iFWjOh7'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            1
        ) AS roast_target_day,
        COALESCE(
            (SELECT cp.value_number
             FROM public.company_parameters cp
             WHERE cp.parameter_id = '1de271df'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            0.82
        ) AS retention_rate,
        COALESCE(
            (SELECT cp.value_number::integer
             FROM public.company_parameters cp
             WHERE cp.parameter_id = 'orders_reset_day'
               AND cp.facility_id  = f.facility_id
             LIMIT 1),
            (SELECT sp.amount::integer
             FROM public.standard_parameters sp
             WHERE sp.parameters_id = 'orders_reset_day'
             LIMIT 1),
            6
        ) AS orders_reset_day
    FROM public.facilities f
),
calc AS (
    SELECT
        fc.facility_id,
        fc.company_id,
        fc.retention_rate,
        ((CURRENT_TIMESTAMP AT TIME ZONE fc.timezone)::date - (
            EXTRACT(dow FROM (CURRENT_TIMESTAMP AT TIME ZONE fc.timezone)::date)::integer
            - fc.orders_reset_day + 7
        ) % 7)                                                          AS order_week_start,
        ((CURRENT_TIMESTAMP AT TIME ZONE fc.timezone)::date - (
            EXTRACT(dow FROM (CURRENT_TIMESTAMP AT TIME ZONE fc.timezone)::date)::integer
            - fc.roast_target_day + 7
        ) % 7)                                                          AS roast_week_start
    FROM facility_config fc
)
SELECT
    c.facility_id                         AS open_order_total_id,
    c.facility_id,
    c.company_id,
    COALESCE(
        (SELECT SUM(od.roasted_weight)
         FROM public.order_details od
         JOIN public.orders o ON od.order_id = o.order_id
         WHERE o.order_date  >= c.order_week_start
           AND o.facility_id  = c.facility_id),
        0::double precision
    )                                     AS total_ordered_roasted,
    COALESCE(
        (SELECT SUM(od.roasted_weight)
         FROM public.order_details od
         JOIN public.orders o ON od.order_id = o.order_id
         WHERE o.order_date  >= c.order_week_start
           AND o.facility_id  = c.facility_id),
        0::double precision
    ) / NULLIF(c.retention_rate::double precision, 0::double precision)
                                          AS total_ordered_green,
    COALESCE(
        (SELECT SUM(rl.roasted_weight)
         FROM public.roast_log rl
         WHERE rl."charged?"   = true
           AND rl.roast_date   >= c.roast_week_start
           AND rl.facility_id   = c.facility_id),
        0::numeric
    )                                     AS total_roasted,
    COALESCE(
        (SELECT SUM(rl.charge_weight)
         FROM public.roast_log rl
         WHERE rl."charged?"   = true
           AND rl.roast_date   >= c.roast_week_start
           AND rl.facility_id   = c.facility_id),
        0::numeric
    )                                     AS total_roasted_green
FROM calc c;

GRANT ALL ON TABLE public.weekly_grand_total TO anon;
GRANT ALL ON TABLE public.weekly_grand_total TO authenticated;
GRANT ALL ON TABLE public.weekly_grand_total TO service_role;

